import React, { useState, useEffect, useRef } from 'react';
import { useThree, useFrame } from '@react-three/fiber';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';

const ModelLoader = ({ modelPath }) => {
  const [model, setModel] = useState(null);
  const groupRef = useRef(null);
  const { scene } = useThree();

  useEffect(() => {
    // Cleanup the previous model
    const cleanupPreviousModel = () => {
      if (model) {
        model.traverse(child => {
          if (child.isMesh) {
            child.geometry.dispose();  // Dispose geometry
            if (child.material.dispose) {
              child.material.dispose();  // Dispose material
            }
          }
        });
        scene.remove(model);  // Remove from scene
        setModel(null);  // Clear model from state
      }
    };

    // Load the new model
    const loader = new OBJLoader();
    loader.load(
      modelPath,
      (obj) => {
        // First, cleanup the previous model before adding a new one
        cleanupPreviousModel();

        // Process new object
        const box = new THREE.Box3().setFromObject(obj);
        const size = box.getSize(new THREE.Vector3());
        const maxDimension = Math.max(size.x, size.y, size.z);
        obj.rotation.x = -Math.PI / 2;
        const scaleFactor = 2.5 / maxDimension;

        obj.scale.set(scaleFactor, scaleFactor, scaleFactor);

        box.setFromObject(obj);
        const center = box.getCenter(new THREE.Vector3());
        obj.position.sub(center);

        // Add new model to the scene
        scene.add(obj);
        setModel(obj);  // Set the new model in state
      },
      undefined,
      (error) => {
        console.error('Error loading OBJ:', error);
      }
    );

    return () => {
      // Cleanup when component unmounts or modelPath changes
      cleanupPreviousModel();
    };
  }, [modelPath, scene, model]);  // Ensure cleanup happens on model change

  useFrame(() => {
    if (groupRef.current) {
      groupRef.current.rotation.y += 0.003;
    }
  });

  return (
    <group ref={groupRef}>
      {!model && (
        <mesh>
          <boxGeometry args={[1, 1, 1]} />
          <meshBasicMaterial color="white" wireframe={true} />
        </mesh>
      )}
    </group>
  );
};

export default ModelLoader;
